var loc = doc.ActiveProjectLocation;
var tr = loc.GetTotalTransform().Inverse;
var res = new List<object>();
foreach (var li in new FilteredElementCollector(doc).OfClass(typeof(RevitLinkInstance)).Cast<RevitLinkInstance>()) {
  var nm = li.Name;
  if (!(nm.Contains("Building 03 Shell") || nm.Contains("Building 03 Internal") || nm.Contains("STR-0011"))) continue;
  var bb = li.get_BoundingBox(null); if (bb == null) continue;
  var c = (bb.Min + bb.Max) / 2;
  var s = tr.OfPoint(c);
  var ld = li.GetLinkDocument();
  string linkSite = ld != null ? ld.ActiveProjectLocation.Name : "unloaded";
  string linkSize = null;
  res.Add(new { nm, centerInternalM = new { x = Math.Round(c.X*0.3048,1), y = Math.Round(c.Y*0.3048,1) }, centerSharedM = new { E = Math.Round(s.X*0.3048,3), N = Math.Round(s.Y*0.3048,3) }, sizeM = new { x = Math.Round((bb.Max.X-bb.Min.X)*0.3048,1), y = Math.Round((bb.Max.Y-bb.Min.Y)*0.3048,1), z = Math.Round((bb.Max.Z-bb.Min.Z)*0.3048,1) }, linkSite, pinned = li.Pinned });
}
return res;
